package com.wheelwright.evidence.v2.portfolio;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioRepository.*;

/** Account-cut owned conservation and fungible economic coverage. Neither establishes buying power. */
public final class PortfolioReconciliation {
 private final PortfolioRepository repository;
 public PortfolioReconciliation(PortfolioRepository repository){this.repository=repository;}
 public ObjectNode calculate(String account,Instant now)throws Exception{
  var result=obj().put("asOf",now.toString()).put("coverage","INCOMPLETE");result.set("account",link("/v2/accounts/"+account));var balances=array();var warnings=array();var assessments=array();result.set("balances",balances);result.set("warnings",warnings);result.set("coverageAssessments",assessments);
  var cut=new PortfolioSnapshots(repository).current(account);if(cut.isEmpty())return result;
  var allHoldings=repository.list(Kind.HOLDING,Set.of(account)).stream().filter(d->Objects.equals(d.snapshot(),cut.get().snapshotId())).toList();var holdings=allHoldings.stream().filter(h->number(h.value().path("quantity"))!=null&&!h.value().path("side").asText().equals("UNKNOWN")).toList();if(holdings.size()!=allHoldings.size())warnings.add(warning("HOLDING_RECONCILIATION_CONFLICT","/balances","Reported monetary figures and unquantified custody observations remain independently readable.","Unknown quantity/direction cannot enter a conservation sum or establish residual buying power."));var byUri=new LinkedHashMap<String,Document>();holdings.forEach(h->byUri.put(h.uri(),h));
  var roots=new ArrayList<ObjectNode>();for(var position:repository.list(Kind.POSITION,Set.of(account)))if(!position.value().path("state").asText().equals("CLOSED")&&(position.snapshot()==null||Objects.equals(position.snapshot(),cut.get().snapshotId())))repository.get(position.value().at("/currentConstruction/href").asText()).ifPresent(c->roots.add(c.value()));
  var used=new HashMap<String,BigDecimal>();var constructions=new HashMap<String,ArrayNode>();var conflicted=new HashSet<String>();boolean complete=allHoldings.size()==holdings.size()&&(holdings.size()==cut.get().holdings().size()+(cut.get().cashObservation()!=null&&cut.get().cashObservation().status().equals("OBSERVED")?1:0))&&(cut.get().cashObservation()==null||cut.get().cashObservation().status().equals("OBSERVED"))&&holdings.stream().allMatch(h->h.value().path("snapshotCoverage").asText().equals("COMPLETE_REPORTED"));
  if(cut.get().cashObservation()!=null&&!cut.get().cashObservation().status().equals("OBSERVED"))warnings.add(warning("HOLDING_RECONCILIATION_CONFLICT","/coverage","Supported securities observations remain independently inspectable.","Companion settled-cash evidence is "+cut.get().cashObservation().status()+"; no complete cash or buying-power conclusion established."));
  var unknownSubjects=new HashSet<String>();for(var holding:allHoldings)if(number(holding.value().path("quantity"))==null||holding.value().path("side").asText().equals("UNKNOWN"))unknownSubjects.add(holding.value().path("instrument").toString());for(var holding:holdings)if(unknownSubjects.contains(holding.value().path("instrument").toString()))conflicted.add(holding.uri());
  for(var root:roots)for(var leaf:leaves(root.path("composition"))){String uri=leaf.at("/allocation/holding/href").asText();var holding=byUri.get(uri);if(holding==null){complete=false;warnings.add(warning("HOLDING_RECONCILIATION_CONFLICT","/balances","Retained observations remain inspectable.","A current allocation does not resolve at this Account cut."));continue;}var inventory=leaf.at("/allocation/inventory");var value=holding.value();boolean same=inventory.path("side").equals(value.path("side"))&&inventory.path("unit").equals(value.path("unit"))&&number(inventory.path("quantity")).compareTo(number(value.path("quantity")))==0&&inventory.path("instrument").equals(value.path("instrument"))&&inventory.path("account").equals(value.path("account"));if(!same){complete=false;conflicted.add(uri);}var quantity=number(leaf.at("/allocation/quantity"));if(quantity==null||quantity.signum()<=0){complete=false;conflicted.add(uri);continue;}used.merge(uri,quantity,BigDecimal::add);constructions.computeIfAbsent(uri,k->array()).add(root.path("self"));}
  for(var holding:holdings){var value=holding.value();var quantity=number(value.get("quantity"));var allocated=used.getOrDefault(holding.uri(),BigDecimal.ZERO);var residual=quantity.subtract(allocated);var inventory=obj().put("key",holding.sourceKey()).put("side",value.path("side").asText()).put("quantity",decimal(quantity)).put("unit",value.path("unit").asText());inventory.set("account",value.path("account"));inventory.set("instrument",value.path("instrument"));if(value.path("unit").asText().equals("MONEY"))inventory.put("currency",value.at("/reportedMarketValue/currency").asText());else inventory.putNull("currency");if(value.has("sourceUnit"))inventory.set("sourceUnit",value.get("sourceUnit"));inventory.set("evidence",value.path("evidence"));inventory.set("holding",value.path("self"));String status=conflicted.contains(holding.uri())?"UNKNOWN":residual.signum()<0?"OVERALLOCATED":"RECONCILED";var balance=obj().put("allocated",decimal(allocated)).put("residual",decimal(residual)).put("status",status).put("availability","UNKNOWN");balance.set("inventory",inventory);balance.set("currentConstructions",constructions.getOrDefault(holding.uri(),array()));balances.add(balance);if(!status.equals("RECONCILED"))warnings.add(warning(status.equals("OVERALLOCATED")?"INVENTORY_OVERALLOCATED":"HOLDING_RECONCILIATION_CONFLICT","/balances/"+(balances.size()-1),"Broker-reported quantity is preserved.","Owned allocations cannot establish complete dependent exposure."));}
  // Requirements group by financial exposure, never by a tax lot or a specific share-to-call association.
  var groups=new LinkedHashMap<String,List<Requirement>>();for(var root:roots){var nodes=new HashMap<String,ObjectNode>();leaves(root.path("composition")).forEach(n->nodes.put(n.path("nodeId").asText(),n));for(var relationship:root.path("relationships"))if(relationship.path("kind").asText().equals("ECONOMIC_COVERAGE")){
   var support=byUri.get(relationship.at("/supportHolding/href").asText());if(support==null){warnings.add(warning("ASSOCIATION_UNRESOLVED","/coverageAssessments","Source observations remain inspectable.","Coverage references a holding outside the current cut."));continue;}
   String unit=support.value().path("unit").asText();if(!Set.of("SHARE","MONEY").contains(unit)){warnings.add(warning("ASSOCIATION_UNRESOLVED","/coverageAssessments","Reported inventory is preserved.","Unsupported coverage unit."));continue;}
   var key=unit+":"+(unit.equals("MONEY")?support.value().at("/reportedMarketValue/currency").asText():support.value().at("/instrument/href").asText());var ids=new TreeSet<String>();relationship.path("toNodes").forEach(n->ids.add(n.asText()));String identity=root.at("/position/href").asText()+ids;
   BigDecimal required=BigDecimal.ZERO;boolean known=Set.of("ESTABLISHED","QUALIFIED").contains(relationship.path("status").asText())&&relationship.at("/authority/basis").asText().equals("AGGREGATE_ECONOMIC_CALCULATION")&&!relationship.path("evidence").isEmpty()&&!ids.isEmpty();
   for(String id:ids){var option=nodes.get(id);if(option==null||!option.path("kind").asText().equals("OPTION")||!option.path("side").asText().equals("SHORT")){known=false;continue;}var terms=option.path("terms");var multiplier=number(terms.path("multiplier"));var deliverable=number(terms.at("/deliverable/0/quantity"));if(multiplier==null||multiplier.signum()<=0||deliverable==null||multiplier.compareTo(deliverable)!=0||!terms.path("payoffApplicability").asText().equals("STANDARD_EQUITY_INTRINSIC")||terms.path("deliverable").size()!=1||!terms.at("/deliverable/0/kind").asText().equals("SHARES")||!terms.path("adjustment").asText().equals("STANDARD")||!terms.path("settlement").asText().equals("PHYSICAL")||!terms.path("underlying").equals(terms.at("/deliverable/0/instrument"))){known=false;continue;}
    if(unit.equals("SHARE")&&(!terms.path("right").asText().equals("CALL")||!terms.path("underlying").equals(support.value().path("instrument")))){known=false;continue;}if(unit.equals("MONEY")&&(!terms.path("right").asText().equals("PUT")||!terms.path("currency").equals(support.value().at("/reportedMarketValue/currency")))){known=false;continue;}
    var amount=number(option.path("quantity")).multiply(multiplier);if(unit.equals("MONEY")){var strike=number(terms.path("strike"));if(strike==null){known=false;continue;}amount=amount.multiply(strike);}required=required.add(amount);
   }
   var claimed=number(relationship.path("quantity"));if(claimed==null||required.compareTo(claimed)!=0)known=false;groups.computeIfAbsent(key,k->new ArrayList<>()).add(new Requirement(identity,root.at("/position/href").asText(),support,required,known));
  }}
  for(var entry:groups.entrySet()){var requirements=entry.getValue();var representative=requirements.getFirst().support();String unit=representative.value().path("unit").asText();var pool=holdings.stream().filter(h->h.value().path("side").asText().equals("LONG")&&h.value().path("unit").asText().equals(unit)&&(unit.equals("MONEY")?h.value().at("/reportedMarketValue/currency").equals(representative.value().at("/reportedMarketValue/currency")):h.value().path("instrument").equals(representative.value().path("instrument")))).toList();var eligible=BigDecimal.ZERO;var supportLinks=array();var evidence=array();for(var h:pool){eligible=eligible.add(number(h.value().get("quantity")));supportLinks.add(h.value().path("self"));for(var e:h.value().path("evidence"))evidence.add(e);}boolean known=!pool.isEmpty()&&!unknownSubjects.contains(representative.value().path("instrument").toString());var distinct=new LinkedHashMap<String,Requirement>();for(var r:requirements){var previous=distinct.putIfAbsent(r.identity(),r);if(previous!=null&&previous.quantity().compareTo(r.quantity())!=0)known=false;known&=r.known();}var required=BigDecimal.ZERO;var obligations=array();var seenPositions=new HashSet<String>();for(var r:distinct.values()){required=required.add(r.quantity());if(seenPositions.add(r.position()))obligations.add(link(r.position()));}
   String status=known?(eligible.compareTo(required)>=0?"SUFFICIENT":"INSUFFICIENT"):"UNKNOWN";var assessment=obj().put("id","aggregate:"+cut.get().snapshotId()+":"+entry.getKey()).put("unit",unit).put("status",status).put("reservationStatus","NOT_ESTABLISHED").put("selection","AGGREGATE_FUNGIBLE_NO_SPECIFIC_SHARE_SELECTION");if(known){assessment.put("eligibleQuantity",decimal(eligible));assessment.put("requiredQuantity",decimal(required));}else{assessment.putNull("eligibleQuantity");assessment.putNull("requiredQuantity");}if(unit.equals("MONEY"))assessment.set("currency",representative.value().at("/reportedMarketValue/currency"));else assessment.putNull("currency");assessment.set("supportHolding",representative.value().path("self"));assessment.set("supportHoldings",supportLinks);assessment.set("obligations",obligations);var subjects=new ArrayList<String>();pool.forEach(h->subjects.add(h.uri()));assessment.set("authority",PortfolioSources.authority(account,"aggregate:"+entry.getKey(),"AGGREGATE_ECONOMIC_CALCULATION",known?"QUALIFIED":"UNRESOLVED",evidence,subjects,"Aggregate current-cut owned fungible support; not broker reservation, available buying power or selected shares."));assessments.add(assessment);if(!status.equals("SUFFICIENT"))warnings.add(warning(known?"COVERAGE_INSUFFICIENT":"ASSOCIATION_UNRESOLVED","/coverageAssessments/"+(assessments.size()-1),"Reported owned quantities remain inspectable.",known?"Aggregate supported obligations exceed eligible owned exposure.":"Required contract terms or association authority are not established."));
  }
  if(complete)result.put("coverage","COMPLETE_CURRENT_ALLOCATIONS");return result;
 }
 private record Requirement(String identity,String position,Document support,BigDecimal quantity,boolean known){}
}
